from fractions import Fraction
import itertools

def can_reach_one(m, n, max_elements=500):
    s = {Fraction(m, n), Fraction(n, m)}
    queue = list(s)
    visited = set(s)
    idx = 0
    while idx < len(queue):
        x = queue[idx]
        idx += 1
        for y in queue[:idx]:
            # AM
            am = (x + y) / 2
            if am == 1: return True
            if am not in visited and len(visited) < max_elements:
                visited.add(am)
                queue.append(am)
            # HM
            hm = 2 * x * y / (x + y)
            if hm == 1: return True
            if hm not in visited and len(visited) < max_elements:
                visited.add(hm)
                queue.append(hm)
    return False

for m_plus_n in range(2, 50):
